def main():
    manifest = []
    for key, text in EXPANDED.items():
        fn = f"{key}.txt"
        with open(os.path.join(OUT_DIR, fn), "w", encoding="utf-8") as f:
            f.write(text)
        manifest.append({
            "key": key, "words": len(text.split()),
            "source": "AI-generated (manually authored to simulate LLM output styles)",
        })
        print(f"  OK {key}: {len(text.split())} 词")
    with open(os.path.join(OUT_DIR, "_manifest.json"), "w", encoding="utf-8") as f:
        json.dump(manifest, f, ensure_ascii=False, indent=2)
    nums = [m["words"] for m in manifest]
    print(f"\n合计 {len(manifest)} 篇，词数 {min(nums)}-{max(nums)}")


if __name__ == "__main__":
    print("=== 扩充 AI 样本 ===\n")
    main()
